def is_not_prime(n: int) -> bool:
    """
    Return True if n is NOT a prime number, False if it is a prime.
    """
    if n < 2:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return True
    return False
```

