def is_sublist(lst: list, sub: list) -> bool:
    """
    Check whether `lst` contains `sub` as a contiguous sublist.
    """
    len_lst = len(lst)
    len_sub = len(sub)

    if len_sub == 0:
        return True
    if len_sub > len_lst:
        return False

    for i in range(len_lst - len_sub + 1):
        if lst[i:i + len_sub] == sub:
            return True
    return False
```

