def is_samepatterns(words, pattern):
    """
    Check whether the words array follows the sequence given in the patterns array.
    Each letter in the pattern must map to exactly one string, and each string must map to exactly one letter.
    """
    if len(words) != len(pattern):
        return False

    char_to_word = {}
    word_to_char = {}

    for word, char in zip(words, pattern):
        if char in char_to_word:
            if char_to_word[char] != word:
                return False
        else:
            char_to_word[char] = word

        if word in word_to_char:
            if word_to_char[word] != char:
                return False
        else:
            word_to_char[word] = char

    return True
```

