def decimal_to_binary(n: int) -> str:
    if n == 0:
        return '0'
    bits = []
    negative = n < 0
    n = abs(n)
    while n > 0:
        bits.append(str(n % 2))
        n //= 2
    if negative:
        return '-' + ''.join(reversed(bits))
    return ''.join(reversed(bits))
