def reverse_vowels(s: str) -> str:
    """
    Reverse only the vowels of a given string.
    Y is not considered a vowel.
    """
    vowels = set('aeiouAEIOU')
    s_chars = list(s)
    left, right = 0, len(s_chars) - 1

    while left < right:
        if s_chars[left] not in vowels:
            left += 1
        elif s_chars[right] not in vowels:
            right -= 1
        else:
            s_chars[left], s_chars[right] = s_chars[right], s_chars[left]
            left += 1
            right -= 1

    return ''.join(s_chars)
```

